import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"الأطروحة الأساسية لمكافحة الافتراس","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0004-反掠夺主义核心论纲.md","filePath":"ar/0004-反掠夺主义核心论纲.md"}'),l={name:"ar/0004-反掠夺主义核心论纲.md"};function o(i,t,h,n,s,_){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="الأطروحة-الأساسية-لمكافحة-الافتراس" tabindex="-1">الأطروحة الأساسية لمكافحة الافتراس <a class="header-anchor" href="#الأطروحة-الأساسية-لمكافحة-الافتراس" aria-label="Permalink to &quot;الأطروحة الأساسية لمكافحة الافتراس&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>04</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>مكافحة الافتراس، نقد الافتراس، البديل التكافلي، الخط الأحمر الأخلاقي، الثورة النظامية</td></tr></tbody></table><h2 id="أولاً-تعريف-الافتراسية-ومظاهرها" tabindex="-1">أولاً: تعريف الافتراسية ومظاهرها <a class="header-anchor" href="#أولاً-تعريف-الافتراسية-ومظاهرها" aria-label="Permalink to &quot;أولاً: تعريف الافتراسية ومظاهرها&quot;">​</a></h2><p>الافتراسية هي رؤية كونية ونظام زراعة تتخذ من الاستيلاء غير المعوَّض وابتلاع واستغلال أصل وطاقة وثروة وموارد كائنات أو مستويات أخرى وسائل مركزية، بهدف تحقيق تطور الذات أو تطور المجموعة. الافتراسية ليست تقنية زراعة محددة، بل موقف جوهري يسري عبر فلسفة الزراعة والمؤسسات الاجتماعية والعلاقات الحضارية.</p><p>في تاريخ هنغ يوانتشو، تجلت الافتراسية في الأشكال الرئيسية التالية:</p><table tabindex="0"><thead><tr><th>الشكل</th><th>المظهر</th><th>الضرر</th></tr></thead><tbody><tr><td>الافتراس الطاقي</td><td>ابتلاع طاقة الزراعة أو أصل كائنات أخرى مباشرة</td><td>يسبب موت المفترَس أو فقدان زراعته بالكامل؛ وينقطع تداول الطاقة الكونية</td></tr><tr><td>افتراس الثروة</td><td>سرقة ثروة الآخرين أو الأعراق بالأسرار</td><td>يسبب انهيار مصير المفترَس وتدهور العرق</td></tr><tr><td>احتكار الطرق</td><td>طوائف قليلة تحتكر طرق الزراعة، مبادلةً التعليم بالولاء والموارد</td><td>يسبب تصلب الطبقات؛ ويفقد الكائنات الدنيا مسارات التطور</td></tr><tr><td>استعمار المستويات</td><td>مستويات عليا تغزو مستويات دنيا وتنهب مواردها وسكانها</td><td>يضر بغشاء المستوى ويؤدي لانهيار أنظمته البيئية</td></tr><tr><td>الاستعباد الروحي</td><td>تحويل كائنات أخرى إلى أدوات زراعة عبر التحكم بالأرواح</td><td>يحرم المستعبَد من إرادته الحرة، منتهكاً كرامة الحياة</td></tr><tr><td>استنزاف الموارد</td><td>استغلال موارد كوكب أو مستوى دون ضوابط</td><td>يسبب انقراضاً بيئياً وتسارع إنتروبيا الكون</td></tr></tbody></table><h2 id="ثانياً-المغالطات-الجوهرية-للافتراسية" tabindex="-1">ثانياً: المغالطات الجوهرية للافتراسية <a class="header-anchor" href="#ثانياً-المغالطات-الجوهرية-للافتراسية" aria-label="Permalink to &quot;ثانياً: المغالطات الجوهرية للافتراسية&quot;">​</a></h2><p>ترى مكافحة الافتراس أن الافتراسية تنطوي على ثلاث مغالطات جوهرية:</p><h3 id="_2-1-مغالطة-الرؤية-الكونية-اعتبار-الكون-ساحة-صيد-محدودة" tabindex="-1">2.1 مغالطة الرؤية الكونية: اعتبار الكون ساحة صيد محدودة <a class="header-anchor" href="#_2-1-مغالطة-الرؤية-الكونية-اعتبار-الكون-ساحة-صيد-محدودة" aria-label="Permalink to &quot;2.1 مغالطة الرؤية الكونية: اعتبار الكون ساحة صيد محدودة&quot;">​</a></h3><p>تعتبر الرؤية الكونية الافتراسية الكون ساحة صيد ذات موارد محدودة، مؤمنة بأن التطور يجب أن يكون لعبة صفرية وأن ترقي القوي يجب أن يكون على حساب تضحية الضعيف. تتجاهل هذه الرؤية «قابلية الكون للتطور» — فالكون ليس حاوية موارد ساكنة، بل كائن حي قادر على الصعود البعدي الشامل عبر التكافل المنظم. وعندما يبتلع المفترسون الضعفاء، فإنهم يستهلكون ليس فقط طاقة الضعفاء، بل الإمكانات التطورية للكون بأسره.</p><h3 id="_2-2-المغالطة-الأخلاقية-وضع-حق-القوي-في-التطور-فوق-حق-الضعيف-في-البقاء" tabindex="-1">2.2 المغالطة الأخلاقية: وضع حق القوي في التطور فوق حق الضعيف في البقاء <a class="header-anchor" href="#_2-2-المغالطة-الأخلاقية-وضع-حق-القوي-في-التطور-فوق-حق-الضعيف-في-البقاء" aria-label="Permalink to &quot;2.2 المغالطة الأخلاقية: وضع حق القوي في التطور فوق حق الضعيف في البقاء&quot;">​</a></h3><p>تتخذ الافتراسية «القوي يلتهم الضعيف» قانوناً طبيعياً، مؤمنة بأن للقوي الحق بل والواجب في التهام الضعيف. تخلط هذه الرؤية الأخلاقية بين الانتقاء الطبيعي والاختيار الأخلاقي. ففي الطبيعة، التهام القوي للضعيف قانون بيئي لا واعٍ؛ أما في الحضارات الزراعية الواعية، فالقوي يمتلك القدرة على الاختيار، وبالتالي يتحمل مسؤولية الاختيار. إن الافتراس المتخفي وراء «طريق السماء» هو في جوهره قيام القوي بتقديم جشعه كقانون كوني.</p><h3 id="_2-3-مغالطة-الكفاءة-الاعتقاد-بأن-الافتراس-أسرع-مسارات-التطور" tabindex="-1">2.3 مغالطة الكفاءة: الاعتقاد بأن الافتراس أسرع مسارات التطور <a class="header-anchor" href="#_2-3-مغالطة-الكفاءة-الاعتقاد-بأن-الافتراس-أسرع-مسارات-التطور" aria-label="Permalink to &quot;2.3 مغالطة الكفاءة: الاعتقاد بأن الافتراس أسرع مسارات التطور&quot;">​</a></h3><p>تدعي الافتراسية أن الافتراس هو أسرع وأكفأ مسارات التطور. لكن على المدى الطويل، يعاني التطور الافتراسي من «سقف كفاءة» خطير: أولاً، غالباً ما تحمل الطاقة المكتسبة بالافتراس إرادة بقايا مالكها الأصلي، مما يتطلب جهوداً هائلة لتصفيتها وتنقيتها؛ ثانياً، تثير الأفعال الافتراسية مقاومة المفترَس ومجموعاته المنتسبة، مما يزيد التكاليف الخارجية للزراعة؛ ثالثاً، يؤدي الاعتماد طويل الأمد على الافتراس إلى تدهور القدرة التطورية الأصلية للمزارع، فيصاب بالركود حال غياب الفريسة؛ رابعاً، غالباً ما يواجه المزارعون المفترسون عنق زجاجة «الأصل غير النقي» عند الاختراق نحو المرتبة العليا، فيصعب عليهم لمس الأصل الكوني حقاً.</p><h2 id="ثالثاً-المقترحات-الأساسية-لمكافحة-الافتراس" tabindex="-1">ثالثاً: المقترحات الأساسية لمكافحة الافتراس <a class="header-anchor" href="#ثالثاً-المقترحات-الأساسية-لمكافحة-الافتراس" aria-label="Permalink to &quot;ثالثاً: المقترحات الأساسية لمكافحة الافتراس&quot;">​</a></h2><p>لا تنفي مكافحة الافتراس ببساطة كل منافسة وكل اختلاف، بل تطرح المقترحات الأساسية التالية:</p><ol><li><strong>يمكن أن يكون التطور غير صفري</strong>: عبر الدورات التكافلية وشبكة المراسي، يمكن لتطور عشرة آلاف عرق أن ينتج تأثيرات تآزرية، محققاً فعالية تطورية يتجاوز فيها الكل مجموع الأجزاء.</li><li><strong>يجب أن تكون المنافسة إبداعية لا تدميرية</strong>: لا تعارض مكافحة الافتراس المنافسة الصحية، لكن يجب أن تأخذ المنافسة شكل رفع القدرة الإبداعية للذات، لا القضاء على القدرة الافتراسية للخصم.</li><li><strong>مسؤولية القوي أكبر من حقوقه</strong>: كلما ارتفعت مرتبة المزارع، زادت مسؤوليته تجاه الشبكة التكافلية، لا زاد حقه في الافتراس. وعلى المزارعين المتقدمين واجب إرشاد المبتدئين والحفاظ على استقرار المراسي وحماية الأمن الحضاري.</li><li><strong>يجب زيادة الموارد بالخلق لا توزيعها بالافتراس</strong>: النهج الأساسي للحضارة التكافلية هو تكبير الكعكة لا تقسيمها، عبر الخلق المستمر لموارد زراعة جديدة بالتقدم التقني وتطبيق القوانين.</li><li><strong>مكافحة الافتراس ليست مساواة مطلقة</strong>: تعارض مكافحة الافتراس الافتراس دون عمل، لا الفروق الناشئة عن «من عمل أكثر نال أكثر». تعترف الحضارة التكافلية بالفروق في النتائج التطورية، لكنها تصر على أن الفروق يجب أن تنبع من جهد الفرد ومساهمته.</li></ol><h2 id="رابعاً-الضمانات-المؤسسية-لمكافحة-الافتراس" tabindex="-1">رابعاً: الضمانات المؤسسية لمكافحة الافتراس <a class="header-anchor" href="#رابعاً-الضمانات-المؤسسية-لمكافحة-الافتراس" aria-label="Permalink to &quot;رابعاً: الضمانات المؤسسية لمكافحة الافتراس&quot;">​</a></h2><p>مكافحة الافتراس ليست مجرد مقترح نظري؛ بل لها سلسلة من الضمانات المؤسسية:</p><ul><li><strong>الضمان القانوني</strong>: يحظر الدستور التكافلي وقانون مكافحة الاحتكار صراحةً السلوك الافتراسي؛ ولمحكمة المرساة اختصاص النظر في قضايا الافتراس</li><li><strong>الضمان الآلي</strong>: يضمن نظام العقود المرتبطة بالإنتاج أن توزيع الموارد يقوم على المساهمة لا العنف؛ وتشرف شبكة المراسي على تدفقات الطاقة غير الطبيعية</li><li><strong>الضمان النظامي</strong>: تستند أنظمة الزراعة الأصلية الثلاثمائة جميعها إلى مبادئ التداول التكافلي؛ ولا توجد طرق افتراسية</li><li><strong>الضمان التعليمي</strong>: يجعل نظام التعليم التكافلي أخلاقيات مكافحة الافتراس مادة إلزامية، مستأصلاً الفكر الافتراسي من جذوره</li><li><strong>الضمان الرقابي</strong>: أنشأت جمعية جمهورية عشرة آلاف عرق لجنة مكافحة الافتراس، تتولى الإشراف على السلوك الافتراسي والتحقيق فيه</li></ul><h2 id="خامساً-السياسة-تجاه-القوى-الافتراسية-المتبقية" tabindex="-1">خامساً: السياسة تجاه القوى الافتراسية المتبقية <a class="header-anchor" href="#خامساً-السياسة-تجاه-القوى-الافتراسية-المتبقية" aria-label="Permalink to &quot;خامساً: السياسة تجاه القوى الافتراسية المتبقية&quot;">​</a></h2><p>إزاء القوى الافتراسية المتبقية التي ما تزال موجودة في الكون، تتبع الحضارة التكافلية سياسة «العزل والتحويل والعقاب»: المفترسون الذين لم يتسببوا بعد في ضرر خطير يتلقون تربية أخلاقية وتحويلاً نظامياً، مع إرشادهم للانضمام إلى النظام التكافلي؛ المفترسون الذين يرفضون التحويل ويواصلون الإضرار بالنظام التكافلي يخضعون لعزل المستوى وتقييد الزراعة؛ المفترسون الذين تسببوا في كوارث كبرى يعاقبون وفقاً للقانون. لا تدعو الحضارة التكافلية إلى مقاومة الافتراس بالافتراس؛ فجميع العقوبات يجب أن تمر عبر المحاكمة العادلة لمحكمة المرساة.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>مكافحة الافتراس هي إحدى الركائز النظرية لحضارة التكافل المرساة. إنها ليست مجرد نقد للنظام الافتراسي القديم، بل بناء إيجابي لإمكانية التطور التكافلي. الهدف النهائي لمكافحة الافتراس ليس القضاء على الأقوياء، بل جعل قوة الأقوياء في خدمة التطور المشترك لعشرة آلاف عرق.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (إعلان حضارة التكافل المرساة)</li><li>03-共生文明宪章 (ميثاق الحضارة التكافلية)</li><li>19-修炼伦理与边界 (أخلاقيات الزراعة وحدودها)</li></ul>',26)])])}const p=a(l,[["render",o]]);export{b as __pageData,p as default};
